import { chromium } from 'playwright'
import assert from 'node:assert/strict'
const browser=await chromium.launch({executablePath:process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH||undefined,args:['--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader']})
const page=await browser.newPage({viewport:{width:1366,height:768}})
const errors=[]
page.on('pageerror',e=>errors.push(e.message))
page.on('console',m=>{if(m.type()==='error')errors.push(m.text())})
const url='http://127.0.0.1:5173/'
try{
  await page.goto(url+'?creator=1',{waitUntil:'domcontentloaded'})
  await page.locator('.site-hero[data-state="ready"]').waitFor({timeout:60000})
  await page.locator('.creator-panel').waitFor()
  const before=await page.evaluate(()=>window.__nocturneAudit())
  assert.ok(before.particles>=9216)
  assert.equal(before.creator,true)
  const set=async(field,value)=>page.locator('[data-field="'+field+'"]').evaluate((el,v)=>{el.value=v;el.dispatchEvent(new Event('input',{bubbles:true}))},value)
  await set('bottle.glassRoughness','0.12')
  await page.waitForFunction(()=>Math.abs(window.__nocturneAudit().bottle.find(m=>m.role==='glass').roughness-.12)<.001)
  await set('lighting.key','3.2')
  await set('particles.repulsion','2')
  await set('particles.momentum','2')
  await set('particles.turbulence','1')
  await set('particles.hue','25')
  await set('atmosphere.saturation','1.3')
  await set('bottle.capRoughness','0.08')
  await set('bottle.goldRoughness','0.3')
  await set('lighting.back','1.2')
  await set('camera.distance','5.4')
  const changed=await page.evaluate(()=>window.__nocturneAudit())
  assert.equal(changed.lights.key,3.2)
  assert.equal(changed.particleControls.repulsion,2)
  assert.equal(changed.particleControls.momentum,2)
  assert.equal(changed.particleControls.turbulence,1)
  assert.equal(changed.particleControls.hue,25)
  assert.equal(changed.lights.rim,2.1)
  assert.equal(changed.camera.z,5.4)
  assert.equal(changed.config.lighting.key,3.2)
  assert.equal(changed.config.particles.repulsion,2)
  assert.equal(changed.config.atmosphere.saturation,1.3)
  assert.equal(changed.config.camera.distance,5.4)
  assert.equal(changed.config.bottle.capRoughness,.08)
  assert.equal(changed.config.bottle.goldRoughness,.3)
  assert.equal(changed.config.lighting.back,1.2)
  await page.reload({waitUntil:'domcontentloaded'})
  await page.locator('.site-hero[data-state="ready"]').waitFor({timeout:60000})
  assert.equal(await page.evaluate(()=>window.__nocturneAudit().config.bottle.glassRoughness),.12)
  await page.locator('.creator-sections details').nth(2).locator('summary').click()
  await page.locator('.creator-sphere-select').selectOption('4')
  await set('sphere.scale','0.2')
  assert.equal(await page.evaluate(()=>window.__nocturneAudit().config.spheres['4'].scale),.2)
  const sphere=await page.evaluate(()=>window.__nocturneAudit().spheres[4])
  const sphereX=await page.evaluate(()=>window.__nocturneAudit().config.spheres['4'].x)
  await page.mouse.move(sphere.x,sphere.y)
  await page.mouse.down()
  await page.mouse.move(sphere.x+28,sphere.y+10,{steps:5})
  await page.mouse.up()
  assert.ok(Math.abs(await page.evaluate(()=>window.__nocturneAudit().config.spheres['4'].x)-sphereX)>.01,'Sphere drag changes its 3D position')
  const handle=page.locator('.creator-sphere-handle')
  await handle.waitFor({state:'visible'})
  const handleBox=await handle.boundingBox()
  const scaleBefore=await page.evaluate(()=>window.__nocturneAudit().config.spheres['4'].scale)
  await page.mouse.move(handleBox.x+handleBox.width/2,handleBox.y+handleBox.height/2)
  await page.mouse.down()
  await page.mouse.move(handleBox.x+handleBox.width/2,handleBox.y-30,{steps:4})
  await page.mouse.up()
  assert.ok(await page.evaluate(()=>window.__nocturneAudit().config.spheres['4'].scale)>scaleBefore,'Direct handle resizes selected sphere')
  await page.locator('.creator-sections details').nth(5).locator('summary').click()
  await page.locator('.creator-brush-tool').selectOption('Warmth')
  await page.mouse.click(220,510)
  assert.ok(await page.evaluate(()=>window.__nocturneAudit().config.brushes.length)>0)
  await page.locator('[data-action="undo"]').click()
  assert.equal(await page.evaluate(()=>window.__nocturneAudit().config.brushes.length),0)
  await page.locator('[data-action="redo"]').click()
  assert.ok(await page.evaluate(()=>window.__nocturneAudit().config.brushes.length)>0)
  const movedSphereX=await page.evaluate(()=>window.__nocturneAudit().config.spheres['4'].x)
  await page.reload({waitUntil:'domcontentloaded'})
  await page.locator('.site-hero[data-state="ready"]').waitFor({timeout:60000})
  assert.equal(await page.evaluate(()=>window.__nocturneAudit().config.spheres['4'].x),movedSphereX)
  await page.locator('.creator-preview').click()
  assert.ok(await page.locator('.creator-panel').isHidden())
  await page.locator('.creator-return').click()
  assert.ok(await page.locator('.creator-panel').isVisible())
  await page.locator('.creator-sections details').nth(6).locator('summary').click()
  await set('camera.zoom','1.2')
  assert.equal(await page.evaluate(()=>window.__nocturneAudit().config.camera.zoom),1.2)
  await page.evaluate(()=>{localStorage.removeItem('nocturne.creator.v1');localStorage.setItem('nocturne.scene-config',JSON.stringify({bottle:{scale:1.2,cameraFov:42,keyLightIntensity:2.7}}))})
  await page.reload({waitUntil:'domcontentloaded'})
  await page.locator('.site-hero[data-state="ready"]').waitFor({timeout:60000})
  assert.equal(await page.evaluate(()=>window.__nocturneAudit().config.bottle.scale),1.2)
  assert.equal(await page.evaluate(()=>window.__nocturneAudit().config.camera.fov),42)
  await page.goto(url,{waitUntil:'domcontentloaded'})
  await page.locator('.site-hero[data-state="ready"]').waitFor({timeout:60000})
  assert.equal(await page.locator('.creator-panel').count(),0)
  assert.equal(await page.evaluate(()=>window.__nocturneAudit().creator),false)
  assert.equal(await page.evaluate(()=>window.__nocturneAudit().bottle.find(m=>m.role==='glass').roughness),.022)
  assert.deepEqual(errors,[])
  console.log('PASS Creator controls, material update, persistence, preview, visitor isolation, runtime errors')
}finally{await browser.close()}
